// Write the reader-facing cautions screen from a prologue's working gaps and cautions, then verify every line.
// args from node tools/args.cjs <topic> cautions. After: node tools/ingest-reader-notes.cjs <topic> <output> --write
// (apply the verifier's fixes to the output file first when it does not pass).
export const meta = {
  name: 'count-reader-cautions',
  description: 'Write the reader-facing version of a prologue\'s gaps and cautions from the sweep\'s working notes, each caution tied to the step it concerns, and verify that every line traces to a note and adds nothing',
  phases: [
    { title: 'Write', detail: 'one Opus writer reads the prologue and writes the reader notes', model: 'opus' },
    { title: 'Verify', detail: 'one Opus verifier traces every line to a working note', model: 'opus' },
  ],
}
const A = args
if (!A || !A.file) throw new Error('args missing; generate them with node tools/args.cjs <topic> cautions')
const ITEM = { type: 'object', properties: { text: { type: 'string' }, from: { type: 'array', items: { type: 'string' } }, steps: { type: 'array', items: { type: 'string' } } }, required: ['text', 'from', 'steps'] }
const NOTES = { type: 'object', properties: { intro: { type: 'string' }, items: { type: 'array', items: ITEM }, stepNotes: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, text: { type: 'string' }, from: { type: 'array', items: { type: 'string' } } }, required: ['id', 'text', 'from'] } }, omitted: { type: 'array', items: { type: 'object', properties: { ref: { type: 'string' }, why: { type: 'string' } }, required: ['ref', 'why'] } } }, required: ['intro', 'items', 'stepNotes', 'omitted'] }
const VERDICT = { type: 'object', properties: { pass: { type: 'boolean' }, problems: { type: 'array', items: { type: 'object', properties: { where: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' } }, required: ['where', 'problem', 'fix'] } }, missing: { type: 'array', items: { type: 'string' } }, summary: { type: 'string' } }, required: ['pass', 'problems', 'missing', 'summary'] }
const RULES = `Rules for every line: it must restate something a working note says, and nothing more; no new facts, no softening and no sharpening. Plain words for a general reader: never "beat", "verifier", "critic", "sweep", "synthesis", "prior outline", "the reader", "entry id", "whyBasis", "thesisBasis", "corpus", "gate", "round" or any id in kebab-case; refer to a step by its subject ("${A.subjectExample || 'the step on the first act'}"). Keep what a reader needs to weigh the record and drop what only records how the file was built (what was dropped between runs, which ids were added, counts of entries per section, wording changes). At most 40 words a line; no em dashes; no loaded adjectives; understate rather than overstate. Each item's "from" lists the working notes it draws on as "gap:N" or "caution:N" (zero-based indexes into the file's gaps and cautions arrays); the dated bracketed updates inside a note count as part of that note. A note and the step it sits on must agree: when a note says a record does not name someone, the step must not name them either; report such a step in the note's text so the operator can fix the step.`
const example = A.example ? ` For the shape, read another edition's readerNotes block in ${A.example} (intro, items with from and steps, stepNotes, omitted).` : ''
phase('Write')
const notes = await agent(`Read ${A.file} (fields: framing, sections[].beats[] with id and line, gaps[], cautions[]; the gaps and cautions are a research sweep's own working notes). The page prints a reader-facing version of those notes on a screen headed "What this prologue cannot support." and folds the notes themselves behind a disclosure.${example} Write this edition's.

Produce: (1) "intro": one or two sentences, in plain words, saying what this screen is and that the full working notes are available below it; (2) "items": the screen's list, in the order a reader should meet them: anything the record supports differently than a reader might expect, then the reasons that are the sweep's reading rather than the entry's statement (name the steps by subject), the dates that are placeholders or stand for a different event than the step describes, the quotations that are cut from longer sentences, the matters that are alleged, disputed, preliminary or still in court, and anything else a reader needs; (3) "stepNotes": for each step that a working note concerns, one line of at most 25 words to print on that step (its id from the file and the text); a step may have more than one line only if the notes say more than one thing about it; (4) "omitted": each working note or part you left off the reader's screen, with why. ${RULES}`, { label: 'write:reader-notes', phase: 'Write', schema: NOTES, model: 'opus', effort: 'high' })
if (!notes) return { error: 'writer returned nothing' }
phase('Verify')
const verdict = await agent(`You are verifying reader-facing notes written from a research sweep's working notes. Open ${A.file} and read its gaps[] and cautions[] (the working notes), its sections[].beats[] (ids, lines, quotes and quoteBy), and its framing. Then check the reader notes below, strictly: (1) every item and every step note restates only what its cited working notes say (the "from" refs are zero-based indexes "gap:N" / "caution:N"); flag any added fact, any softening, any sharpening, and any wrong "from" ref; (2) every step note's id exists in the file and the cited note really concerns that step, and the note does not contradict what the step itself prints (a quoteBy, a date); (3) no banned process words ("beat", "verifier", "critic", "sweep", "synthesis", "prior outline", "the reader", "entry id", "whyBasis", "thesisBasis", "corpus", "gate", "round", kebab-case ids), no em dashes, no loaded adjectives, each line at most 40 words (step notes at most 25); (4) coverage: list in "missing" any working note, or part of one, that a reader needs to weigh the record and that neither the items nor the step notes carry and that "omitted" does not justify. Set pass=false if any problem is a misstatement or a coverage gap; give an exact replacement text for each problem.

Reader notes (JSON):
${JSON.stringify(notes, null, 1)}`, { label: 'verify:reader-notes', phase: 'Verify', schema: VERDICT, model: 'opus', effort: 'high' })
return { notes, verdict }
